import{_ as d,o as e,a,b as p}from"./app.UgfkfLuP.js";const l=JSON.parse('{"title":"","description":"","frontmatter":{"breadcrumbs":[{"text":"Ascend C算子开发指南","link":"/guide/getting_started/ascend_c_overview_and_learning_path"},{"text":"技术附录","link":"/guide/technical_appendix/technical_appendix"},{"text":"C++标准支持","link":"/guide/technical_appendix/cpp_standard_support/cpp_standard_support"},{"text":"Device侧C++语言支持","link":"/guide/technical_appendix/cpp_standard_support/cpp_language_feature/cpp_language_feature"},{"text":"C++17语言特性","link":"/guide/technical_appendix/cpp_standard_support/cpp_language_feature/cpp17_language_feature"}]},"headers":[],"relativePath":"guide/technical_appendix/cpp_standard_support/cpp_language_feature/cpp17_language_feature.md","filePath":"guide/technical_appendix/cpp_standard_support/cpp_language_feature/cpp17_language_feature.md","lastUpdated":1792570027000}'),r={name:"guide/technical_appendix/cpp_standard_support/cpp_language_feature/cpp17_language_feature.md"};function s(c,t,o,n,_,g){return e(),a("div",null,[...t[0]||(t[0]=[p('<div><article class="markdown-body"><h1>C++17语言特性</h1><p>本文介绍C++17语言特性在Ascend C Device侧的支持情况。</p><p><strong>表1</strong> C++17语言特性支持列表</p><table><thead><tr><th>C++17特性</th><th>C++17 Proposal</th><th>是否支持</th><th>说明</th></tr></thead><tbody><tr><td>移除trigraphs</td><td><a href="https://www.open-std.org/jtc1/sc22/wg21/docs/papers/2014/n4086.html">N4086</a></td><td>是</td><td>三字符组不再转译。</td></tr><tr><td>u8字符字面量</td><td><a href="https://www.open-std.org/jtc1/sc22/wg21/docs/papers/2014/n4267.html">N4267</a></td><td>是</td><td><code>u8&#39;x&#39;</code>形式可用。</td></tr><tr><td>命名空间与枚举器属性</td><td><a href="https://www.open-std.org/jtc1/sc22/wg21/docs/papers/2014/n4266.html">N4266</a></td><td>是</td><td><code>namespace [[maybe_unused]] ns {...}</code>、枚举器携带属性可用。</td></tr><tr><td>嵌套命名空间定义</td><td><a href="https://www.open-std.org/jtc1/sc22/wg21/docs/papers/2014/n4230.html">N4230</a></td><td>是</td><td><code>namespace a::b::c {...}</code>形式可用。</td></tr><tr><td>非类型模板参数的常量求值</td><td><a href="https://www.open-std.org/jtc1/sc22/wg21/docs/papers/2014/n4268.html">N4268</a></td><td>是</td><td>—</td></tr><tr><td>模板模板参数允许typename</td><td><a href="https://www.open-std.org/jtc1/sc22/wg21/docs/papers/2014/n4051.html">N4051</a></td><td>是</td><td><code>template &lt;template &lt;typename&gt; typename TT&gt;</code>形式可用。</td></tr><tr><td><code>[[fallthrough]]</code>属性</td><td><a href="https://www.open-std.org/jtc1/sc22/wg21/docs/papers/2016/p0188r1.pdf">P0188R1</a></td><td>是</td><td>—</td></tr><tr><td><code>[[nodiscard]]</code>属性</td><td><a href="https://www.open-std.org/jtc1/sc22/wg21/docs/papers/2016/p0189r1.pdf">P0189R1</a></td><td>是</td><td>忽略返回值会产生告警。</td></tr><tr><td><code>[[maybe_unused]]</code>属性</td><td><a href="https://www.open-std.org/jtc1/sc22/wg21/docs/papers/2016/p0212r1.pdf">P0212R1</a></td><td>是</td><td>—</td></tr><tr><td>constexpr lambda</td><td><a href="https://www.open-std.org/jtc1/sc22/wg21/docs/papers/2016/p0170r1.pdf">P0170R1</a></td><td>是</td><td><code>constexpr auto f = [...] constexpr {...}</code>编译期调用可用</td></tr><tr><td>一元折叠与空参数包</td><td><a href="https://www.open-std.org/jtc1/sc22/wg21/docs/papers/2015/p0036r0.pdf">P0036R0</a></td><td>是</td><td>—</td></tr><tr><td>lambda按值捕获<code>*this</code></td><td><a href="https://www.open-std.org/jtc1/sc22/wg21/docs/papers/2016/p0018r3.html">P0018R3</a></td><td>是</td><td><code>[*this]</code>捕获当前对象副本，SIMD与SIMT混合编程场景写法见<a href="./lambda_expressions.html">Lambda表达式</a>。</td></tr><tr><td>enum class构造规则</td><td><a href="https://www.open-std.org/jtc1/sc22/wg21/docs/papers/2016/p0138r2.pdf">P0138R2</a></td><td>是</td><td>整型可直接列表初始化enum class。</td></tr><tr><td>十六进制浮点字面量</td><td><a href="https://www.open-std.org/jtc1/sc22/wg21/docs/papers/2016/p0245r1.html">P0245R1</a></td><td>是</td><td><code>0x1.8p3</code>形式可用。</td></tr><tr><td><code>__has_include</code></td><td><a href="https://wg21.link/p0061">P0061R1</a></td><td>是</td><td>—</td></tr></tbody></table></article></div>',1)])])}const w=d(r,[["render",s]]);export{l as __pageData,w as default};
